import React, { useState } from 'react';
import { Box, Button, IconButton, Stack, TextField, Tooltip, Typography } from '@mui/material';
import { useNavigate, Link } from 'react-router-dom';
import { signInWithEmailAndPassword } from "firebase/auth";
import { auth } from '../../firebaseConfig/page';
import Loader from '../../loader/Loader';
import UIText from '../../utilities/textResource';
import { RiArrowGoBackFill } from 'react-icons/ri';

const SignInPage: React.FC = () => {
    const navigate = useNavigate();
    const [isLoading, setIsLoading] = useState(false);
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [errors, setErrors] = useState({ email: '', password: '' });

    // handle return to login
    const handleReturnToLogin = () => {
        navigate('/');
    }

    // Email Validation
    const validateEmail = (email: string) => {
        if (!email.trim()) return "Email is required";
        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        return emailRegex.test(email) ? "" : "Invalid email format";
    };

    // Password Validation
    const validatePassword = (password: string) => {
        if (!password.trim()) return "Password is required";
        const passwordRegex = /^.{6,}$/; // Allows any password with at least 6 characters
        return passwordRegex.test(password) ? "" : "Password must be at least 6 characters long.";
    };

    // hanlde email change to get latest data from email input
    const handleEmailChange = (e: any) => {
        setEmail(e.target.value);
        setErrors((prev) => ({ ...prev, email: validateEmail(e.target.value) }));
    };

    // hanlde password change to get latest data from password input
    const handlePasswordChange = (e: any) => {
        const value = e.target.value;
        setPassword(value);
        const errorMsg = validatePassword(value);
        setErrors((prev) => ({ ...prev, password: errorMsg }));
    };

    // handle sign in with email authenticate user with firebase 
    const handleLoginWithEmail = async () => {
        const emailError = validateEmail(email);
        const passwordError = validatePassword(password);

        setErrors({ email: emailError, password: passwordError });

        if (emailError || passwordError) return;

        try {
            setIsLoading(true);
            const userCredential = await signInWithEmailAndPassword(auth, email, password);
            const user = userCredential.user;

            const accessToken = await user.getIdToken();
            const refreshToken = user.refreshToken;

            localStorage.setItem("access_token", accessToken);
            localStorage.setItem("refresh_token", refreshToken);

            setIsLoading(false);
            navigate('/research_editor');
        } catch (error) {
            setIsLoading(false);
            setErrors({ email: "", password: "Invalid email or password" });
        }
    };

    // Disable sign-in button if there are validation errors or fields are empty
    const isButtonDisabled = !!errors.email || !!errors.password || !email || !password;

    return (
        <>
            {isLoading && <Loader />}
            <Stack sx={{ minHeight: "100vh", height: "auto", backgroundColor: "#ffffff" }}>
                <Stack
                    sx={{
                        display: "flex",
                        flexDirection: "column",
                        justifyContent: "start",
                        alignItems: "center",
                        textAlign: "center",
                        width: "100%",
                    }}
                >
                    <Stack sx={{
                        display: "flex",
                        flexDirection: "row",
                        alignItems: "center",
                        justifyContent: "space-between",
                        width: "90%",
                        padding: "8px"
                    }}>
                        <Tooltip title="Return to Signin" placement="right-start">
                            <IconButton
                                aria-label="Return to Login"
                                size="small"
                                sx={{ fontSize: "20px" }}
                                onClick={handleReturnToLogin}
                            >
                                <RiArrowGoBackFill />
                            </IconButton>
                        </Tooltip>

                        <Typography
                            sx={{
                                fontSize: "24px",
                                fontWeight: "bold",
                                color: "#5E17EB",
                                letterSpacing: "2px",
                                fontFamily: "monospace",
                                flexGrow: 1,
                                textAlign: "center",
                                position: "absolute",
                                left: "50%",
                                transform: "translateX(-50%)"
                            }}
                        >
                            {UIText.auth.limit} <span style={{ color: "black" }}>{UIText.auth.up}</span>
                        </Typography>
                    </Stack>

                    <Typography
                        sx={{
                            fontSize: "16px",
                            maxWidth: "300px",
                            fontFamily: "monospace",
                            padding: "12px 16px",
                            fontWeight: "600",
                            letterSpacing: "1px",
                        }}
                    >
                        {UIText.auth.description}
                    </Typography>
                </Stack>

                <Stack sx={{ margin: "30px 12px 20px 12px" }}>
                    <TextField
                        label="Email"
                        variant="outlined"
                        size="small"
                        value={email}
                        onChange={handleEmailChange}
                        error={!!errors.email}
                        helperText={errors.email}
                        sx={{ width: "100%", maxWidth: "600px", marginBottom: "16px" }}
                    />
                    <TextField
                        label="Password"
                        variant="outlined"
                        size="small"
                        type="password"
                        value={password}
                        onChange={handlePasswordChange}
                        error={!!errors.password}
                        helperText={errors.password}
                        sx={{ width: "100%", maxWidth: "600px" }}
                    />
                </Stack>

                <Stack sx={{ display: "flex", justifyContent: "center", alignItems: "center" }}>
                    <Button
                        variant="outlined"
                        sx={{
                            borderRadius: "24px",
                            color: "white",
                            textTransform: "none",
                            fontSize: "1rem",
                            fontWeight: 500,
                            padding: "6px 36px",
                            border: "none",
                            marginTop: "16px",
                            transition: "all 0.3s ease-in-out",
                            opacity: isButtonDisabled ? 0.6 : 1,
                            cursor: isButtonDisabled ? "not-allowed" : "pointer",
                            background: isButtonDisabled ? "#ccc" : "linear-gradient(to right, #5E17EB, #0BB670)",
                        }}
                        onClick={handleLoginWithEmail}
                    >
                        <span>{UIText.auth.sign_in}</span>
                    </Button>
                </Stack>
                <Stack sx={{ display: "flex", justifyContent: "center", alignItems: "center" }}>
                    <Typography
                        sx={{
                            fontSize: "12px",
                            maxWidth: "300px",
                            fontFamily: "monospace",
                            padding: "12px 16px",
                            fontWeight: "400",
                            letterSpacing: "1px",
                            textAlign: "center"
                        }}
                    >
                        {UIText.auth.if_you_have_no_account}
                        <Link
                            to="/signup_with_email_and_password"
                            style={{ textDecoration: "underline", color: "#006BD6" }}
                        >
                            {UIText.auth.signup_with_email_and_password.sign_up}
                        </Link>
                    </Typography>
                </Stack>
            </Stack>
        </>
    );
};

export default SignInPage;