import React, { useState, useEffect } from "react";
import { Stack, Typography, Button } from "@mui/material";
import Loader from "../../loader/Loader";
import Toast from "../../toast/Toast";
import UIText from "../../utilities/textResource";
import { useNavigate } from "react-router-dom";
import { debugLog } from "../../utilities/debugLog";

const SignIn: React.FC = () => {
    const navigate = useNavigate();
    const [error, setError] = useState('');
    const [isLoading, setIsLoading] = useState(false);

    useEffect(() => {
        const access_token = localStorage.getItem("access_token");
        const refresh_token = localStorage.getItem("refresh_token");
        if (access_token && refresh_token) navigate("/research_editor");
    }, []);

    // login with google
    const handleSigninWithGoogle = () => {
        setIsLoading(true);

        Office.context.ui.displayDialogAsync(
            // "https://localhost:3000/assets/redirect.html",
            "https://waqasahmed042.github.io/limit-up/assets/redirect.html",
            { height: 70, width: 50, displayInIframe: false },
            function (asyncResult: { status: any; error: { message: any; }; value: any; }) {
                if (asyncResult.status === Office.AsyncResultStatus.Failed) {
                    debugLog("signin.tsx, Line no: 29, Dialog Failed to Open:", asyncResult.error.message);
                    setIsLoading(false);
                    return;
                }

                const dialog = asyncResult.value;

                // Handle Messages from the Auth Window
                dialog.addEventHandler(Office.EventType.DialogMessageReceived, async (event: { message: string; }) => {
                    try {
                        if ("message" in event && typeof event.message === "string") {
                            const response = JSON.parse(event.message);

                            if (response.success) {
                                debugLog("signin.tsx, Line no: 44, User Info:", response.user);

                                const user = response.user;
                                const accessToken = user.stsTokenManager.accessToken;
                                const refreshToken = user.stsTokenManager.refreshToken;

                                localStorage.setItem("access_token", accessToken);
                                localStorage.setItem("refresh_token", refreshToken);

                                setIsLoading(false);
                                navigate('/research_editor');
                            } else {
                                debugLog("signin.tsx, Line no: 56, Login Failed:", response.error);
                                setError(response.error);
                            }
                        } else {
                            debugLog("signin.tsx, Line no: 60, Unexpected event format:", event);
                        }
                    } catch (error) {
                        debugLog("signin.tsx, Line no: 63, Failed to parse message:", error);
                    } finally {
                        dialog.close();
                        setIsLoading(false);
                    }
                });
            }
        );
    };

    // sign in with email & password
    const handleSigninWithEmail = () => {
        navigate("/signin_with_email_and_password");
    }

    return (
        <>
            {isLoading && <Loader />}
            <Stack
                sx={{
                    display: "flex",
                    flexDirection: "column",
                    justifyContent: "start",
                    alignItems: "center",
                    height: "100vh",
                    textAlign: "center",
                }}
            >
                <Typography
                    sx={{
                        fontSize: "24px",
                        fontWeight: "bold",
                        color: "#5E17EB",
                        letterSpacing: "2px",
                        padding: "16px",
                        fontFamily: "monospace",
                    }}
                >
                    {UIText.auth.limit} <span style={{ color: "black" }}>{UIText.auth.up}</span>
                </Typography>

                <Typography
                    sx={{
                        fontSize: "16px",
                        maxWidth: "300px",
                        fontFamily: "monospace",
                        padding: "12px 16px",
                        fontWeight: "600",
                        letterSpacing: "1px",
                    }}
                >
                    {UIText.auth.description}
                </Typography>

                <Button
                    onClick={handleSigninWithGoogle}
                    variant="outlined"
                    sx={{
                        display: "flex",
                        alignItems: "center",
                        gap: 1,
                        backgroundColor: "white",
                        borderRadius: "24px",
                        color: "black",
                        boxShadow: 2,
                        textTransform: "none",
                        fontSize: "1rem",
                        fontWeight: 500,
                        padding: "6px 16px",
                        border: "1px solid #ccc",
                        marginTop: "16px",
                        "&:hover": {
                            backgroundColor: "gray.100",
                        },
                    }}
                >
                    <img src="https://waqasahmed042.github.io/limit-up/assets/google.png" alt="Google" height={20} width={20} />
                    <span>{UIText.auth.signin_with_google}</span>
                </Button>

                <Button
                    onClick={handleSigninWithEmail}
                    variant="outlined"
                    sx={{
                        display: "flex",
                        alignItems: "center",
                        gap: 1,
                        background: "linear-gradient(to right, #5E17EB, #0BB670)",
                        borderRadius: "24px",
                        color: "white",
                        textTransform: "none",
                        fontSize: "1rem",
                        fontWeight: 500,
                        padding: "6px 36px",
                        border: "none",
                        marginTop: "16px",
                        transition: "all 0.3s ease-in-out"
                    }}
                >
                    <span>{UIText.auth.signin_with_email}</span>
                </Button>
            </Stack>

            {/* Show toast when error, info, or success */}
            <Toast error={error} />
        </>
    );
};

export default SignIn;