import { debugLog } from "./debugLog";

export const getSelectedText = async (callback: (arg0: null, arg1: string) => void) => {
    try {
        await Word.run(async (context) => {
            const selection = context.document.getSelection();
            selection.load("text");

            await context.sync();
            const text = selection.text.trim() ? selection.text : null;
            callback(null, text);
        });
    } catch (error) {
        debugLog("getSelectedText.ts, Line no: 14, Error getting selected text:", error);
        callback(error, null);
    }
};