import Groq from 'groq-sdk';
import { ChatCompletionMessageParam } from 'groq-sdk/resources/chat/completions';
import { debugLog } from '../utilities/debugLog';

const groq = new Groq({
    apiKey: "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",
    dangerouslyAllowBrowser: true
});

export const enhanceSelectedText = async (selectedText: string, prompt: string, callback: (error: Error | null, data: string | null) => void): Promise<void> => {
    try {
        // Define messages with proper type
        const messages: ChatCompletionMessageParam[] = [
            { role: 'system', content: selectedText },
            { role: 'user', content: prompt }
        ];

        // Create chat completion with typed parameters
        const chatCompletion = await groq.chat.completions.create({
            messages: messages,
            model: 'llama3-70b-8192',
            temperature: 1,
            max_completion_tokens: 1024,
            top_p: 1,
            stream: false,
            stop: null
        });

        // Safely access and log the content
        const responseContent = chatCompletion.choices[0]?.message?.content;
        callback(null, responseContent)
    } catch (error) {
        debugLog('grog.ts, Line no: 33, Error in Groq API call:', error);
        callback(error, null)
    }
}