import React, { useState, useEffect } from "react";
import { Slide, Dialog, DialogContent, DialogActions, Typography, TextField, Button, IconButton } from "@mui/material";
import { TransitionProps } from "@mui/material/transitions";
import { PromptDialogProps } from "../../utilities/type";
import { RiCloseFill } from "react-icons/ri";
import UIText from "../../utilities/textResource";

// Slide transition for the dialog animation
const Transition = React.forwardRef(function Transition(
    props: TransitionProps & { children: React.ReactElement<any, any> },
    ref: React.Ref<unknown>
) {
    return <Slide direction="up" ref={ref} {...props} />;
});

const PromptDialog: React.FC<PromptDialogProps> = ({ open, setOpen, promptToEdit, onSave }) => {
    const [name, setName] = useState("");
    const [prompt, setPrompt] = useState("");
    const [promptNameError, setPromptNameError] = useState("");
    const [promptError, setPromptError] = useState("");

    // Ensures input is empty when creating a new prompt
    useEffect(() => {
        setPrompt(promptToEdit ? promptToEdit.text : "");
        setPromptError("");
    }, [promptToEdit, open]);

    // Ensures input is empty when creating a new prompt
    useEffect(() => {
        if (promptToEdit) {
            setName(promptToEdit.name ?? "");
            setPrompt(promptToEdit.text ?? "");
        } else {
            setName("");
            setPrompt("");
        }
        setPromptError("");
        setPromptNameError("");
    }, [promptToEdit, open]);

    // Handle saving the prompt with validation
    const handleSave = () => {
        let hasError = false;

        if (!name.trim()) {
            setPromptNameError(UIText.custom_prompt_manager.prompt_Dialog.prompt_name_cannot_be_empty);
            hasError = true;
        } else if (name.length > 15) {
            setPromptNameError(UIText.custom_prompt_manager.prompt_Dialog.character_length);
            hasError = true;
        }

        if (!prompt.trim()) {
            setPromptError(UIText.custom_prompt_manager.prompt_Dialog.not_create_while_empty);
            hasError = true;
        }

        if (hasError) return;

        onSave({ name, text: prompt });
        setOpen(false);
    };

    return (
        <>
            <Dialog
                open={open}
                fullWidth
                TransitionComponent={Transition}
                onClose={() => setOpen(false)}
            >
                <DialogContent
                    sx={{
                        display: "flex",
                        flexDirection: "column",
                        alignItems: "start",
                        padding: "20px",
                        position: "relative",
                        gap: "10px",
                        pb: "0px",
                    }}
                >
                    <IconButton
                        sx={{
                            position: "absolute",
                            top: 8,
                            right: 8,
                            color: "gray",
                        }}
                        onClick={() => setOpen(false)}
                    >
                        <RiCloseFill size={22} />
                    </IconButton>

                    <Typography variant="h6" sx={{ fontWeight: "bold", fontSize: "14px" }}>
                        {promptToEdit ? UIText.custom_prompt_manager.prompt_Dialog.edit_custom_prompt :
                            UIText.custom_prompt_manager.prompt_Dialog.custom_prompt}
                    </Typography>

                    <TextField
                        label="Prompt Name"
                        variant="filled"
                        size="small"
                        value={name}
                        onChange={(e) => {
                            setName(e.target.value);
                            if (e.target.value.trim().length > 0) setPromptNameError("");
                        }}
                        error={!!promptNameError}
                        sx={{ width: "100%" }}
                    />
                    <Typography sx={{ color: "red", fontSize: "12px" }}>{promptNameError}</Typography>

                    <TextField
                        label="Enter your prompt"
                        variant="filled"
                        multiline
                        rows={4}
                        maxRows={6}
                        value={prompt}
                        onChange={(e) => {
                            setPrompt(e.target.value);
                            if (e.target.value.trim().length > 0) setPromptError("");
                        }}
                        error={!!promptError}
                        sx={{ width: "100%" }}
                    />
                </DialogContent>
                <Typography sx={{ color: "red", fontSize: "12px", padding: "4px 20px" }}>{promptError}</Typography>

                <DialogActions sx={{ justifyContent: "center", paddingBottom: "16px", marginTop: "12px" }}>
                    <Button
                        variant="outlined"
                        onClick={handleSave}
                        sx={{
                            display: "flex",
                            alignItems: "center",
                            gap: 1,
                            background: "linear-gradient(to right, #5E17EB, #0BB670)",
                            borderRadius: "24px",
                            color: "white",
                            textTransform: "none",
                            fontSize: "1rem",
                            fontWeight: 500,
                            padding: "6px 25px",
                            border: "none",
                            transition: "all 0.3s ease-in-out",
                        }}
                    >
                        {promptToEdit ? UIText.custom_prompt_manager.prompt_Dialog.update_prompt :
                            UIText.custom_prompt_manager.prompt_Dialog.create_custom_prompt}
                    </Button>
                </DialogActions>
            </Dialog>
        </>
    );
};

export default PromptDialog;