import React from "react";
import { MemoryRouter as Router, Routes, Route } from "react-router-dom";
import SignIn from "../pages/signin/page";
import ResearchEditor from "../pages/researchEditor/page";
import CustomPromptManager from "../pages/customPromptManager/page";
import SystemPrompt from "../pages/systemPrompt/page";
import SignUpPage from "../pages/signin/signupWithEmail";
import SignInPage from "../pages/signin/signinWithEmail";

const RouterApp: React.FC = () => {
    return (
        <Router>
            <Routes>
                <Route path="/" element={<SignIn />} />
                <Route path="/signin_with_email_and_password" element={<SignInPage />} />
                <Route path="/signup_with_email_and_password" element={<SignUpPage />} />
                <Route path="/research_editor" element={<ResearchEditor />} />
                <Route path="/custom_prompt_manager" element={<CustomPromptManager />} />
                <Route path="/system_prompt" element={<SystemPrompt />} />
            </Routes>
        </Router>
    )
}

export default RouterApp;