import React, { useState, useEffect } from 'react';
import { Stack, IconButton, Typography, TextField, Tooltip } from '@mui/material';
import { RiArrowGoBackFill } from 'react-icons/ri';
import UIText from '../../utilities/textResource';
import { useNavigate } from 'react-router-dom';
import { IoMdLogOut } from 'react-icons/io';
import { getAuth, signOut } from 'firebase/auth';
import { debugLog } from '../../utilities/debugLog';

const page: React.FC = () => {
    const navigate = useNavigate();
    const [systemPrompt, setSystemPrompt] = useState(UIText.system_prompt.prompt);

    // Store systemPrompt in localStorage every time it changes
    useEffect(() => {
        localStorage.setItem("systemPrompt", systemPrompt);
    }, [systemPrompt]);

    // handle return icon click
    const handleReturnToResearchEditor = () => {
        navigate("/research_editor");
    };

    // handle logged out user from firebase and moved to signin page
    const auth = getAuth();
    const handleLogout = async () => {
        try {
            await signOut(auth);
            localStorage.removeItem("access_token");
            localStorage.removeItem("refresh_token");

            navigate("/");
        } catch (error) {
            debugLog("systemPrompt.tsx, Line no: 33, Logout failed:", error);
        }
    };

    return (
        <>
            <Stack
                sx={{
                    display: "flex",
                    flexDirection: "column",
                    justifyContent: "start",
                    alignItems: "center",
                    textAlign: "center",
                    width: "100%",
                }}
            >
                <Stack sx={{
                    display: "flex",
                    flexDirection: "row",
                    alignItems: "center",
                    justifyContent: "space-between",
                    width: "90%",
                    marginTop: "8px",
                    padding: "8px"
                }}>
                    <Tooltip title="Return to Editor" placement="right-start">
                        <IconButton
                            aria-label="Return to Editor"
                            size="small"
                            sx={{ fontSize: "20px" }}
                            onClick={handleReturnToResearchEditor}
                        >
                            <RiArrowGoBackFill />
                        </IconButton>
                    </Tooltip>

                    <Typography
                        sx={{
                            fontSize: "24px",
                            fontWeight: "bold",
                            color: "#5E17EB",
                            letterSpacing: "2px",
                            fontFamily: "monospace",
                            flexGrow: 1,
                            textAlign: "center",
                            position: "absolute",
                            left: "50%",
                            transform: "translateX(-50%)"
                        }}
                    >
                        {UIText.auth.limit} <span style={{ color: "black" }}>{UIText.auth.up}</span>
                    </Typography>

                    <Tooltip title="Logout" placement="left-start">
                        <IconButton
                            aria-label="Logout"
                            size="small"
                            sx={{ fontSize: "20px" }}
                            onClick={handleLogout}
                        >
                            <IoMdLogOut />
                        </IconButton>
                    </Tooltip>
                </Stack>

                <Typography sx={{ fontSize: "20px", fontWeight: "bold", fontFamily: "monospace" }}>
                    {UIText.system_prompt.title}
                </Typography>
                <Typography
                    sx={{
                        fontSize: "14px",
                        maxWidth: "300px",
                        fontFamily: "monospace",
                        padding: "0px 16px 16px 16px",
                        fontWeight: "400",
                    }}
                >
                    {UIText.system_prompt.description}
                </Typography>
            </Stack>

            <Stack
                sx={{
                    display: "flex",
                    flexDirection: "column",
                    alignItems: "start",
                    padding: "20px",
                    position: "relative",
                    gap: "10px",
                    pb: "0px",
                }}
            >
                <TextField
                    label="System prompt"
                    variant="filled"
                    multiline
                    rows={13}
                    value={systemPrompt}
                    onChange={(e) => setSystemPrompt(e.target.value)}
                    sx={{ width: "100%", marginBottom: "16px" }}
                />
            </Stack>
        </>
    );
};

export default page;