import React, { useState, useEffect } from 'react';
import { Box, Button, IconButton, Stack, Tooltip, Typography } from '@mui/material';
import UIText from '../../utilities/textResource';
import { HiPlusSm } from "react-icons/hi";
import Loader from '../../loader/Loader';
import Toast from '../../toast/Toast';
import { useNavigate } from 'react-router-dom';
import { enhanceSelectedText } from '../../services/grog';
import { getSelectedText } from '../../utilities/getSelectedText';
import { replaceSelectedText } from '../../utilities/replcaeSelectedText';
import { IoMdLogOut } from 'react-icons/io';
import { getAuth, signOut } from "firebase/auth";
import { debugLog } from '../../utilities/debugLog';

const Home: React.FC = () => {
    const navigate = useNavigate();
    const [isLoading, setIsLoading] = useState(false);
    const [info, setInfo] = useState("");
    const [error, setError] = useState("");
    const [success, setSuccess] = useState("");
    const [prompts, setPrompts] = useState<string[]>([]);

    // hanlde return to custom prompt manager page
    const handleCustomePrompt = () => {
        navigate('/custom_prompt_manager');
    }

    // handle enhance selected text in Word document
    const handleEnhanceSelectedText = async () => {
        setInfo("");
        setError("");
        setSuccess("");

        const prompt = localStorage.getItem("systemPrompt") ??
            UIText.research_editor.prompt.enhance_prompt;

        await getSelectedText(async (error, selectedText) => {
            if (error) {
                debugLog("researchEditor.tsx, Line no: 39, Error fetching selected text:", error);
                setError("Error fetching selected text.");
                setIsLoading(false);
                return;
            }

            if (!selectedText) {
                setInfo("No text selected. Please select text to enhance.");
                return;
            }

            if (selectedText && prompt) {
                try {
                    setIsLoading(true);

                    enhanceSelectedText(selectedText, prompt, async (error, data) => {
                        setIsLoading(false);
                        if (error) {
                            debugLog("researchEditor.tsx, Line no: 57, Error fetching AI response:", error);
                            setError("Error enhancing text.");
                        } else if (data) {
                            debugLog("researchEditor.tsx, Line no: 60, Success fetching AI response:", data);
                            await replaceSelectedText(data);
                            setSuccess("Text enhanced successfully.");
                        }
                    });
                } catch (error) {
                    debugLog("researchEditor.tsx, Line no: 66, Error enhancing text:", error);
                    setError("Unexpected error occurred.");
                    setIsLoading(false);
                }
            }
        });
    };

    useEffect(() => {
        const storedPrompts = JSON.parse(localStorage.getItem("customPrompts") || "[]");
        setPrompts(storedPrompts);
    }, []);

    // handle return to system prompt
    const handleSystemPrompt = async () => {
        navigate('/system_prompt');
    }

    // Enhance text using a custom prompt
    const handlePromptClick = async (prompt: string) => {
        setError("");
        setSuccess("");
        setInfo("");

        await getSelectedText(async (error, selectedText) => {
            if (error) {
                debugLog("researchEditor.tsx, Line no: 92, Error fetching selected text:", error);
                setError("Error fetching selected text.");
                setIsLoading(false);
                return;
            }

            if (!selectedText) {
                setInfo("No text selected. Please select text to enhance.");
                return;
            }

            try {
                if (selectedText && prompt) {
                    setIsLoading(true);

                    enhanceSelectedText(selectedText, prompt, async (error, data) => {
                        setIsLoading(false);
                        if (error) {
                            debugLog("researchEditor.tsx, Line no: 110, Error fetching AI response:", error);
                            setError("Error enhancing text.");
                        } else if (data) {
                            debugLog("researchEditor.tsx, Line no: 113, Success fetching AI response:", data);
                            await replaceSelectedText(data);
                            setSuccess("Text enhanced successfully.");
                        }
                    });
                }
            } catch (error) {
                debugLog("researchEditor.tsx, Line no: 120, Error enhancing text:", error);
                setError("Unexpected error occurred.");
                setIsLoading(false);
            }
        });
    };

    // handle logged out user from firebase and moved to signin page
    const auth = getAuth();
    const handleLogout = async () => {
        try {
            await signOut(auth);
            localStorage.removeItem("access_token");
            localStorage.removeItem("refresh_token");

            navigate("/");
        } catch (error) {
            console.error("Logout failed:", error);
        }
    };

    return (
        <>
            {isLoading && (<Loader />)}
            <Stack sx={{ minHeight: "100vh", height: prompts.length > 1 ? "auto" : "100vh", backgroundColor: "#ffffff" }}>
                <Stack
                    sx={{
                        display: "flex",
                        flexDirection: "column",
                        justifyContent: "start",
                        alignItems: "center",
                        textAlign: "center",
                        width: "100%",
                    }}
                >
                    <Stack
                        sx={{
                            display: "flex",
                            flexDirection: "row",
                            alignItems: "center",
                            justifyContent: "center",
                            width: "90%",
                            marginTop: "8px",
                            padding: "8px",
                            position: "relative"
                        }}
                    >
                        <Typography
                            sx={{
                                fontSize: "24px",
                                fontWeight: "bold",
                                color: "#5E17EB",
                                letterSpacing: "2px",
                                fontFamily: "monospace",
                                textAlign: "center",
                                flexGrow: 1,
                            }}
                        >
                            {UIText.auth.limit} <span style={{ color: "black" }}>{UIText.auth.up}</span>
                        </Typography>

                        <Tooltip title="Logout" placement="left-start">
                            <IconButton
                                aria-label="Logout"
                                size="small"
                                sx={{ fontSize: "20px" }}
                                onClick={handleLogout}
                            >
                                <IoMdLogOut />
                            </IconButton>
                        </Tooltip>
                    </Stack>

                    <Typography sx={{ fontSize: "32px", fontWeight: "bold", fontFamily: "monospace" }}>
                        {UIText.research_editor.title}
                    </Typography>
                    <Typography
                        sx={{
                            fontSize: "16px",
                            maxWidth: "300px",
                            fontFamily: "monospace",
                            padding: "0px 16px 16px 16px",
                            fontWeight: "400",
                        }}
                    >
                        {UIText.research_editor.description}
                    </Typography>
                </Stack>

                <Box sx={{ display: "flex", flexDirection: "column", justifyContent: "center", alignItems: "center" }}>
                    <Button
                        variant="outlined"
                        sx={{
                            display: "flex",
                            alignItems: "center",
                            gap: 1,
                            background: "linear-gradient(to right, #5E17EB, #0BB670)",
                            borderRadius: "24px",
                            color: "white",
                            textTransform: "none",
                            fontSize: "1rem",
                            fontWeight: 500,
                            padding: "6px 36px",
                            border: "none",
                            transition: "all 0.3s ease-in-out"
                        }}
                        onClick={handleEnhanceSelectedText}
                    >
                        <span>{UIText.research_editor.buttons.enhance}</span>
                    </Button>

                    <Stack sx={{ marginTop: "8px", gap: "8px" }}>
                        {prompts.map((prompt: any, index: number) => (
                            <Box key={index} sx={{ display: "flex", alignItems: "center", justifyContent: "space-between" }}>
                                <Button
                                    variant="outlined"
                                    sx={{
                                        flex: 1,
                                        display: "flex",
                                        justifyContent: "center",
                                        alignItems: "center",
                                        gap: 1,
                                        background: "linear-gradient(to right, #5E17EB, #0BB670)",
                                        borderRadius: "24px",
                                        color: "white",
                                        textTransform: "none",
                                        fontSize: "1rem",
                                        fontWeight: 500,
                                        padding: "6px 31px"
                                    }}
                                    onClick={() => handlePromptClick(prompt.text)}
                                >
                                    <span>{prompt.name}</span>
                                </Button>
                            </Box>
                        ))}
                    </Stack>
                </Box>

                <Box
                    sx={{
                        display: "flex",
                        flexDirection: "column",
                        justifyContent: "center",
                        alignItems: "center",
                        paddingBottom: "16px",
                        position: prompts.length > 1 ? "" : "fixed",
                        bottom: prompts.length > 1 ? "" : "8px",
                        marginTop: prompts.length > 1 ? "16px" : "8px",
                        width: "100%"
                    }}
                >
                    <Button
                        variant="outlined"
                        sx={{
                            display: "flex",
                            alignItems: "center",
                            gap: 1,
                            background: "linear-gradient(to right, #5E17EB, #BF6AE3)",
                            borderRadius: "24px",
                            color: "white",
                            textTransform: "none",
                            fontSize: "1rem",
                            fontWeight: 500,
                            padding: "6px 36px",
                            border: "none",
                            marginTop: "8px",
                            transition: "all 0.3s ease-in-out",
                        }}
                        endIcon={<HiPlusSm />}
                        onClick={handleCustomePrompt}
                    >
                        <span>{UIText.research_editor.buttons.custom_prompts}</span>
                    </Button>

                    <Button
                        variant="outlined"
                        sx={{
                            display: "flex",
                            alignItems: "center",
                            gap: 1,
                            background: "linear-gradient(to right, #FF3732, #FF8A4B)",
                            borderRadius: "24px",
                            color: "white",
                            textTransform: "none",
                            fontSize: "1rem",
                            fontWeight: 500,
                            padding: "6px 36px",
                            border: "none",
                            marginTop: "8px",
                            transition: "all 0.3s ease-in-out",
                        }}
                        onClick={handleSystemPrompt}
                    >
                        <span>{UIText.research_editor.buttons.system_prompt}</span>
                    </Button>
                </Box>
            </Stack>

            {/* Show toast when error, info, or success */}
            <Toast error={error} success={success} info={info} />
        </>
    );
};

export default Home;