import { debugLog } from "./debugLog";

export const replaceSelectedText = async (enhanced_text: string) => {
    try {
        await Word.run(async (context) => {
            const selection = context.document.getSelection();

            // Apply justification formatting before inserting text
            const paragraph = selection.paragraphs.getFirst();
            paragraph.alignment = Word.Alignment.justified;
            await context.sync();

            selection.insertText(enhanced_text + "\n", Word.InsertLocation.replace);
            await context.sync();
        });
    } catch (error) {
        debugLog("replaceSelectedText.ts, Line no: 19, Unexpected error replacing text:", error);
    }
};