import React, { useState, useEffect } from 'react';
import { Stack, IconButton, Typography, Button, Box, Tooltip } from '@mui/material';
import { RiArrowGoBackFill, RiDeleteBin5Line } from 'react-icons/ri';
import { IoMdLogOut } from "react-icons/io";
import { TbEditCircle } from "react-icons/tb";
import UIText from '../../utilities/textResource';
import { HiPlusSm } from 'react-icons/hi';
import { useNavigate } from 'react-router-dom';
import PromptDialog from './promptDialog';
import { getAuth, signOut } from 'firebase/auth';
import { debugLog } from '../../utilities/debugLog';

const CustomPromptManager: React.FC = () => {
    const navigate = useNavigate();
    const [open, setOpen] = useState(false);
    const [prompts, setPrompts] = useState<{ name: string; text: string }[]>([]);
    const [editPrompt, setEditPrompt] = useState<{ name: string; text: string } | null>(null);

    useEffect(() => {
        const storedPrompts = JSON.parse(localStorage.getItem("customPrompts") || "[]");
        setPrompts(storedPrompts);
    }, []);

    // handle return icon click
    const handleReturnToResearchEditor = () => {
        navigate("/research_editor");
    };

    // open dialog for creating custom prompt
    const handleCustomPrompt = () => {
        setEditPrompt(null);
        setOpen(true);
    };

    const handleSavePrompt = (newPrompt: { name: string; text: string }) => {
        let updatedPrompts;
        if (editPrompt) {
            updatedPrompts = prompts.map((p) => (p.text === editPrompt?.text ? newPrompt : p));
        } else {
            updatedPrompts = [...prompts, newPrompt];
        }
        setPrompts(updatedPrompts);
        localStorage.setItem("customPrompts", JSON.stringify(updatedPrompts));
    };

    const handleEditPrompt = (prompt: { name: string; text: string }) => {
        setEditPrompt(prompt);
        setOpen(true);
    };

    const handleDeletePrompt = (prompt: { name: string; text: string }) => {
        const updatedPrompts = prompts.filter((p) => p.text !== prompt.text);
        setPrompts(updatedPrompts);
        localStorage.setItem("customPrompts", JSON.stringify(updatedPrompts));
    };

    // handle logged out user from firebase and moved to signin page
    const auth = getAuth();
    const handleLogout = async () => {
        try {
            await signOut(auth);
            localStorage.removeItem("access_token");
            localStorage.removeItem("refresh_token");

            navigate("/");
        } catch (error) {
            debugLog("customPromptManager.tsx, Line no: 67, Logout failed:", error);
        }
    };

    return (
        <>
            <Stack sx={{ minHeight: "100vh", height: "auto", backgroundColor: "#ffffff" }}>
                <Stack
                    sx={{
                        display: "flex",
                        flexDirection: "column",
                        justifyContent: "start",
                        alignItems: "center",
                        textAlign: "center",
                        width: "100%",
                    }}
                >
                    <Stack sx={{
                        display: "flex",
                        flexDirection: "row",
                        alignItems: "center",
                        justifyContent: "space-between",
                        width: "90%",
                        marginTop: "8px",
                        padding: "8px"
                    }}>
                        <Tooltip title="Return to Editor" placement="right-start">
                            <IconButton
                                aria-label="Return to Editor"
                                size="small"
                                sx={{ fontSize: "20px" }}
                                onClick={handleReturnToResearchEditor}
                            >
                                <RiArrowGoBackFill />
                            </IconButton>
                        </Tooltip>

                        <Typography
                            sx={{
                                fontSize: "24px",
                                fontWeight: "bold",
                                color: "#5E17EB",
                                letterSpacing: "2px",
                                fontFamily: "monospace",
                                flexGrow: 1,
                                textAlign: "center",
                                position: "absolute",
                                left: "50%",
                                transform: "translateX(-50%)"
                            }}
                        >
                            {UIText.auth.limit} <span style={{ color: "black" }}>{UIText.auth.up}</span>
                        </Typography>

                        <Tooltip title="Logout" placement="left-start">
                            <IconButton
                                aria-label="Logout"
                                size="small"
                                sx={{ fontSize: "20px" }}
                                onClick={handleLogout}
                            >
                                <IoMdLogOut />
                            </IconButton>
                        </Tooltip>
                    </Stack>

                    <Typography sx={{ fontSize: "20px", fontWeight: "bold", fontFamily: "monospace" }}>
                        {UIText.custom_prompt_manager.title}
                    </Typography>
                    <Typography
                        sx={{
                            fontSize: "14px",
                            maxWidth: "300px",
                            fontFamily: "monospace",
                            padding: "0px 16px 16px 16px",
                            fontWeight: "400",
                        }}
                    >
                        {UIText.custom_prompt_manager.description}
                    </Typography>
                </Stack>

                <Stack sx={{ justifyContent: "center", alignItems: "center", margin: "16px" }}>
                    <Button
                        variant="outlined"
                        onClick={handleCustomPrompt}
                        sx={{
                            display: "flex",
                            alignItems: "center",
                            gap: 1,
                            background: "linear-gradient(to right, #5E17EB, #BF6AE3)",
                            borderRadius: "24px",
                            color: "white",
                            textTransform: "none",
                            fontSize: "1rem",
                            fontWeight: 500,
                            padding: "6px 36px",
                            border: "none",
                            transition: "all 0.3s ease-in-out",
                        }}
                        endIcon={<HiPlusSm />}
                    >
                        {UIText.custom_prompt_manager.custom_prompt}
                    </Button>

                    <Stack sx={{ marginTop: "16px", gap: "8px" }}>
                        {prompts.map((prompt, index) => (
                            <Box key={index} sx={{ display: "flex", alignItems: "center", justifyContent: "space-between" }}>
                                <Button
                                    variant="outlined"
                                    sx={{
                                        flex: 1,
                                        display: "flex",
                                        justifyContent: "center",
                                        alignItems: "center",
                                        gap: 1,
                                        background: "linear-gradient(to right, #5E17EB, #0BB670)",
                                        borderRadius: "24px",
                                        color: "white",
                                        textTransform: "none",
                                        fontSize: "1rem",
                                        fontWeight: 500,
                                        padding: "6px 31px"
                                    }}
                                >
                                    <span>{prompt.name}</span>
                                </Button>
                                <Box sx={{ display: "flex", gap: "2px", marginLeft: "6px" }}>
                                    <IconButton onClick={() => handleEditPrompt(prompt)}>
                                        <TbEditCircle size={24} />
                                    </IconButton>
                                    <IconButton onClick={() => handleDeletePrompt(prompt)}>
                                        <RiDeleteBin5Line size={24} />
                                    </IconButton>
                                </Box>
                            </Box>
                        ))}
                    </Stack>
                </Stack>
            </Stack>

            {open && (
                <PromptDialog
                    open={open}
                    setOpen={setOpen}
                    promptToEdit={editPrompt}
                    onSave={handleSavePrompt}
                />
            )}
        </>
    );
};

export default CustomPromptManager;