import React, { useState } from 'react';
import { Box, Button, IconButton, Stack, TextField, Tooltip, Typography } from '@mui/material';
import { Link, useNavigate } from 'react-router-dom';
import { createUserWithEmailAndPassword } from "firebase/auth";
import { auth } from '../../firebaseConfig/page';
import Loader from '../../loader/Loader';
import UIText from '../../utilities/textResource';
import { RiArrowGoBackFill } from 'react-icons/ri';

const SignUpPage: React.FC = () => {
    const navigate = useNavigate();
    const [isLoading, setIsLoading] = useState(false);
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [confirmPassword, setConfirmPassword] = useState('');
    const [errors, setErrors] = useState({ email: '', password: '', confirmPassword: '' });

    // Handle return to login
    const handleReturnToLogin = () => {
        navigate('/');
    };

    // Email Validation
    const validateEmail = (email: string) => {
        if (!email.trim()) return "Email is required";
        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        return emailRegex.test(email) ? "" : "Invalid email format";
    };

    // Password Validation
    const validatePassword = (password: string) => {
        if (!password.trim()) return "Password is required";
        const passwordRegex = /^(?=.*[A-Z])(?=.*\d)(?=.*[@#$%^&*!])[A-Za-z\d@#$%^&*!]{8,}$/;
        if (!passwordRegex.test(password)) {
            return "Must be at least 8 characters, contain 1 uppercase, 1 number, and 1 special symbol.";
        }
        return "";
    };

    // Confirm Password Validation
    const validateConfirmPassword = (password: string, confirmPassword: string) => {
        if (!confirmPassword.trim()) return "Confirm Password is required";
        return password === confirmPassword ? "" : "Passwords do not match";
    };

    // Handle email change
    const handleEmailChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        setEmail(e.target.value);
        setErrors((prev) => ({ ...prev, email: validateEmail(e.target.value) }));
    };

    // Handle password change
    const handlePasswordChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const value = e.target.value;
        setPassword(value);
        const errorMsg = validatePassword(value);
        setErrors((prev) => ({
            ...prev,
            password: errorMsg,
            confirmPassword: validateConfirmPassword(value, confirmPassword),
        }));
    };

    // handle confirm password change
    const handleConfirmPasswordChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const value = e.target.value;
        setConfirmPassword(value);
        setErrors((prev) => ({
            ...prev,
            confirmPassword: validateConfirmPassword(password, value),
        }));
    };

    // handle sign up with email authenticate user with firebase
    const handleLoginWithEmail = async () => {
        const emailError = validateEmail(email);
        const passwordError = validatePassword(password);
        const confirmPasswordError = validateConfirmPassword(password, confirmPassword);

        setErrors({ email: emailError, password: passwordError, confirmPassword: confirmPasswordError });

        if (emailError || passwordError || confirmPasswordError) return;

        try {
            setIsLoading(true);
            const userCredential = await createUserWithEmailAndPassword(auth, email, password);
            const user = userCredential.user;

            const accessToken = await user.getIdToken();
            const refreshToken = user.refreshToken;

            localStorage.setItem("access_token", accessToken);
            localStorage.setItem("refresh_token", refreshToken);

            setIsLoading(false);
            navigate('/research_editor');
        } catch (error) {
            setIsLoading(false);
            setErrors((prev) => ({ ...prev, email: "", password: "Invalid email or password" }));
        }
    };

    // Disable sign-up button if there are validation errors or fields are empty
    const isButtonDisabled = !!errors.email || !!errors.password || !!errors.confirmPassword || !email || !password || !confirmPassword;


    return (
        <>
            {isLoading && <Loader />}
            <Stack sx={{ minHeight: "100vh", height: "auto", backgroundColor: "#ffffff" }}>
                <Stack
                    sx={{
                        display: "flex",
                        flexDirection: "column",
                        justifyContent: "start",
                        alignItems: "center",
                        textAlign: "center",
                        width: "100%",
                    }}
                >
                    <Stack sx={{
                        display: "flex",
                        flexDirection: "row",
                        alignItems: "center",
                        justifyContent: "space-between",
                        width: "90%",
                        padding: "8px"
                    }}>
                        <Tooltip title="Return to Signin" placement="right-start">
                            <IconButton
                                aria-label="Return to Login"
                                size="small"
                                sx={{ fontSize: "20px" }}
                                onClick={handleReturnToLogin}
                            >
                                <RiArrowGoBackFill />
                            </IconButton>
                        </Tooltip>

                        <Typography
                            sx={{
                                fontSize: "24px",
                                fontWeight: "bold",
                                color: "#5E17EB",
                                letterSpacing: "2px",
                                fontFamily: "monospace",
                                flexGrow: 1,
                                textAlign: "center",
                                position: "absolute",
                                left: "50%",
                                transform: "translateX(-50%)"
                            }}
                        >
                            {UIText.auth.limit} <span style={{ color: "black" }}>{UIText.auth.up}</span>
                        </Typography>
                    </Stack>

                    <Typography
                        sx={{
                            fontSize: "16px",
                            maxWidth: "300px",
                            fontFamily: "monospace",
                            padding: "12px 16px",
                            fontWeight: "600",
                            letterSpacing: "1px",
                        }}
                    >
                        {UIText.auth.description}
                    </Typography>
                </Stack>

                <Stack sx={{ margin: "24px 12px 20px 12px" }}>
                    <TextField
                        label="Email"
                        variant="outlined"
                        size="small"
                        value={email}
                        onChange={handleEmailChange}
                        error={!!errors.email}
                        helperText={errors.email}
                        sx={{ width: "100%", maxWidth: "600px", marginBottom: "16px" }}
                    />
                    <TextField
                        label="Password"
                        variant="outlined"
                        size="small"
                        type="password"
                        value={password}
                        onChange={handlePasswordChange}
                        error={!!errors.password}
                        helperText={errors.password}
                        sx={{ width: "100%", maxWidth: "600px", marginBottom: "16px" }}
                    />
                    <TextField
                        label="Confirm Password"
                        variant="outlined"
                        size="small"
                        type="password"
                        value={confirmPassword}
                        onChange={handleConfirmPasswordChange}
                        error={!!errors.confirmPassword}
                        helperText={errors.confirmPassword}
                        sx={{ width: "100%", maxWidth: "600px" }}
                    />
                </Stack>

                <Stack sx={{ display: "flex", justifyContent: "center", alignItems: "center" }}>
                    <Button
                        variant="outlined"
                        sx={{
                            borderRadius: "24px",
                            color: "white",
                            textTransform: "none",
                            fontSize: "1rem",
                            fontWeight: 500,
                            padding: "6px 36px",
                            border: "none",
                            marginTop: "12px",
                            transition: "all 0.3s ease-in-out",
                            opacity: isButtonDisabled ? 0.6 : 1,
                            cursor: isButtonDisabled ? "not-allowed" : "pointer",
                            background: isButtonDisabled ? "#ccc" : "linear-gradient(to right, #5E17EB, #0BB670)",
                        }}
                        onClick={handleLoginWithEmail}
                    >
                        <span>{UIText.auth.signup_with_email_and_password.sign_up}</span>
                    </Button>
                </Stack>
                <Stack sx={{ display: "flex", justifyContent: "center", alignItems: "center" }}>
                    <Typography
                        sx={{
                            fontSize: "12px",
                            maxWidth: "300px",
                            fontFamily: "monospace",
                            padding: "12px 16px",
                            fontWeight: "400",
                            letterSpacing: "1px",
                            textAlign: "center"
                        }}
                    >
                        {UIText.auth.if_you_have_no_account}
                        <Link
                            to="/signin_with_email_and_password"
                            style={{ textDecoration: "underline", color: "#006BD6" }}
                        >
                            {UIText.auth.sign_in}
                        </Link>
                    </Typography>
                </Stack>
            </Stack>
        </>
    );
};

export default SignUpPage;